form.sfo_javascript:
nuUserHomeCheckNoObjectsOnForm();

function openNuObject() {

    $('#nuMessageDiv').remove();
    nuPopup('nuobject', '-1', window.nuFORM.getCurrent().form_id);

}

function nuUserHomeCheckNoObjectsOnForm() {
    if (nuSERVERRESPONSE.objects.length === 0 && window.global_access) {
        const message = `${nuTranslate('There are currently no objects on this form.')}&nbsp;&nbsp;
            <a href="javascript:openNuObject();">${nuTranslate('Start adding some')}</a>.`;

        $.nuInfoBar.info(message, {autoClose : false, closeOnClick : true});
    }
}
